<script setup lang="ts">
import {computed,ref,watch,onMounted} from 'vue'
import Icon from './Icon.vue'
import type {StorageState,StorageKeep} from './types'
const bridge=window.aiLink
const props=defineProps<{storage?:StorageState;busy:string}>()
const emit=defineEmits<{action:[method:string,params:Record<string,unknown>,message:string];error:[message:string];notice:[message:string]}>()
const empty:StorageState={items:[],updated:0,batches:[],cloud_count:0,root:'',library:'',pinned:[],cloud_connection:'export_only'}
const data=computed(()=>props.storage||empty),source=ref<'local'|'cloud'>('local'),selected=ref<string[]>([]),workspace=ref(''),olderDays=ref(30),fromDate=ref(''),toDate=ref(''),includeLogs=ref(false)
const keep=ref<StorageKeep>({files:true,final:true,decisions:true,code:false}),label=ref(''),nativeBusy=ref(false),reviewed=ref(false),draftRevision=ref(0),previewRevision=ref(-1)
const cache=ref<{bytes:number;scope:string}|null>(null)
const locked=computed(()=>!!props.busy||nativeBusy.value)
const scopeItems=computed(()=>data.value.items.filter(r=>r.source===source.value))
const workspaces=computed(()=>[...new Set(scopeItems.value.filter(r=>r.kind==='conversation').map(r=>r.workspace))])
const start=computed(()=>fromDate.value?new Date(fromDate.value+'T00:00:00').getTime()/1000:null),end=computed(()=>toDate.value?new Date(toDate.value+'T23:59:59').getTime()/1000:null)
const filtered=computed(()=>scopeItems.value.filter(r=>(!workspace.value||r.workspace===workspace.value)&&(!start.value||r.updated>=start.value)&&(!end.value||r.updated<=end.value)&&r.updated<=Date.now()/1000-olderDays.value*86400&&(r.kind!=='log'||includeLogs.value)))
const visibleLimit=ref(100)
const visibleItems=computed(()=>filtered.value.slice(0,visibleLimit.value))
const eligible=computed(()=>filtered.value.filter(r=>!r.protected))
watch([source,workspace,olderDays,fromDate,toDate,includeLogs],()=>visibleLimit.value=100)
const preview=computed(()=>data.value.preview?.source===source.value&&previewRevision.value===draftRevision.value?data.value.preview:null)
const batches=computed(()=>data.value.batches.filter(b=>b.source===source.value))
const labels:Record<string,string>={archived:'已归档 · 可恢复',quarantined:'日志已回收',archive_pending:'归档结果待核实',pending:'处理中',failed:'未完成',restored:'已恢复',purged:'原始记录已永久清除',delete_pending:'删除结果待核实',cloud_pending:'云端待处理 · 本地成果已保留'}
const categories=[{key:'files' as const,name:'输出文件',text:'安全链接指向的文件；工作区原文件始终保留',icon:'folder'},{key:'final' as const,name:'最终答复',text:'最终阶段的答复，缺失时保留最后一次回答',icon:'check'},{key:'decisions' as const,name:'重要结论',text:'按结论、约束、验证、待办等明确文字提取',icon:'shield'},{key:'code' as const,name:'代码片段',text:'保留最终答复中的完整 Markdown 代码块',icon:'terminal'}]
watch([source,workspace,olderDays,fromDate,toDate,includeLogs,keep,selected],()=>{draftRevision.value++;reviewed.value=false},{deep:true})
watch(source,()=>{selected.value=[];workspace.value='';previewRevision.value=-1})
watch(()=>data.value.preview?.token,()=>{if(data.value.preview?.source===source.value)previewRevision.value=draftRevision.value})
watch(()=>data.value.items,()=>{const next=selected.value.filter(id=>scopeItems.value.some(i=>i.id===id&&!i.protected));if(next.join('|')!==selected.value.join('|'))selected.value=next})
const bytes=(n:number)=>n<1024?n+' B':n<1048576?(n/1024).toFixed(1)+' KiB':(n/1048576).toFixed(1)+' MiB'
const date=(n:number)=>n?new Date(n*1000).toLocaleDateString():'未知日期'
function scan(){selected.value=[];emit('action','storage.scan',{source:source.value},'扫描完成，请核对范围与保护标记。')}
function selectEligible(){selected.value=eligible.value.slice(0,20).map(r=>r.id)}
function requestPreview(){emit('action','storage.preview',{ids:selected.value,policy:{source:source.value,workspace:workspace.value,olderDays:olderDays.value,from:start.value,to:end.value,keep:{...keep.value},includeLogs:includeLogs.value}},'预览已生成，尚未改变任何对话。')}
async function native(action:()=>Promise<unknown>,message:string,refresh=false){if(locked.value)return;nativeBusy.value=true;try{const result=await action();if(result!==null&&result!==false){emit('notice',message);if(refresh)emit('action','storage.refresh',{},message)}}catch(error){emit('error',String(error).replace(/^Error: /,''))}finally{nativeBusy.value=false}}
async function readCache(){try{cache.value=await bridge.appCache()}catch{}}
onMounted(readCache)
</script>
<template><div class="workspace-page storage-page" :class="`storage-${source}`"><section class="panel storage-hero"><div><span class="eyebrow">RETENTION STUDIO</span><h2>留下成果，整理过程。</h2><p>先预览影响，再处理记录。让对话、成果与缓存，各归其位。</p></div><div class="retention-visual" aria-hidden="true"><span class="retention-ring ring-one"></span><span class="retention-ring ring-two"></span><Icon name="archive" :size="38"/><i></i><i></i><i></i></div></section>
<div class="storage-sources" role="group" aria-label="清理分区"><button class="storage-source local-source" :class="{selected:source==='local'}" :aria-pressed="source==='local'" :disabled="locked" @click="source='local'"><Icon name="terminal" :size="23"/><span><strong>本机 Codex</strong><small>会话归档 · 日志 · 可恢复回收区</small></span><span class="source-dot"></span></button><button class="storage-source cloud-source" :class="{selected:source==='cloud'}" :aria-pressed="source==='cloud'" :disabled="locked" @click="source='cloud'"><Icon name="cloud" :size="23"/><span><strong>ChatGPT 云端</strong><small>导出整理 · 成果保留 · 官方待处理</small></span><span class="source-dot"></span></button></div>
<div v-if="data.error" class="notice warning" role="alert"><Icon name="info"/><p>{{ data.error }}</p></div>
<section v-if="source==='cloud'" class="panel cloud-import-panel"><div class="section-heading"><div><span class="eyebrow muted">CLOUD EXPORTS</span><h3>先把云端成果带回本地</h3><p>导入官方导出的 ZIP／conversations JSON。原导出包保留原位，应用不读取登录凭据。</p></div><span class="badge subtle">{{ data.cloud_count }} 段已导入</span></div><div class="cloud-import-controls"><label class="sr-only" for="cloud-group">账户／导出分组</label><input id="cloud-group" v-model="label" maxlength="40" placeholder="账户或导出分组，例如：个人账号 · 产品项目" :disabled="locked"><button class="btn primary cloud-import" :disabled="locked||!label.trim()" @click="native(()=>bridge.importCloudExport(label),'导出包已导入，云端没有发生变化。',true)"><Icon name="upload" :size="16"/>导入官方导出包</button><button class="btn secondary" :disabled="locked" @click="native(()=>bridge.openCloudCleanup(),'已打开 ChatGPT 官方页面。')"><Icon name="globe" :size="16"/>打开 ChatGPT</button></div><details class="retention-help"><summary>导出教程与云端处理边界 <Icon name="down" :size="15"/></summary><ol><li>在 ChatGPT 官方设置的数据控制中申请导出，下载收到的 ZIP；也可导入其中的 conversations JSON。</li><li>输入分组名称区分账户或项目，再导入。导出没有可靠项目归属时，分组只是本地标签。</li><li>筛选日期、选择保留成果，生成清单。原始云端聊天、保存的记忆、Library 文件分别管理，不能互相替代。</li><li>清单中的“在官方页面处理”打开原对话，由你确认归档或删除。本应用不会声称云端已删除；没有保存到本地的附件链接也不会显示为文件已下载。</li></ol></details><p class="cloud-boundary"><Icon name="info" :size="15"/>当前为导出整理模式，未连接云端删除接口。原导出包、云端聊天、保存的记忆与 Library 文件均不会被本地整理自动删除。</p></section>
<section class="storage-metrics"><article class="panel"><span>当前分区记录</span><strong>{{ scopeItems.length }}</strong><small>{{ source==='local'?'扫描后显示本机对话与旧日志':'导入后的本地索引' }}</small></article><article class="panel"><span>匹配且可选</span><strong>{{ eligible.length }}</strong><small>{{ bytes(eligible.reduce((n,r)=>n+r.bytes,0)) }} 原始记录</small></article><article class="panel"><span>自动排除</span><strong>{{ filtered.filter(r=>r.protected).length }}</strong><small>重要、守护中或状态需要核实</small></article></section>
<section class="panel retention-policy"><div class="section-heading"><div><span class="eyebrow muted">SCOPE & PRESERVATION</span><h3>定义本次整理范围</h3><p>日期按本机时区筛选；本机最近 24 小时有更新的记录始终保护。</p></div><button class="btn secondary storage-scan" :disabled="locked" @click="scan"><Icon name="refresh" :size="16"/>{{ source==='local'?'扫描本机记录':'刷新导出索引' }}</button></div><div class="retention-filters"><label>工作区／导出分组<select id="storage-workspace" v-model="workspace" :disabled="locked"><option value="">全部工作区</option><option v-for="value in workspaces" :key="value" :value="value">{{ value }}</option></select></label><label>闲置至少<select id="storage-age" v-model.number="olderDays" :disabled="locked"><option :value="0">不限天数</option><option :value="7">7 天</option><option :value="30">30 天</option><option :value="90">90 天</option><option :value="365">一年</option></select></label><label>更新开始日期<input id="storage-from" v-model="fromDate" type="date" :disabled="locked"></label><label>更新结束日期<input id="storage-to" v-model="toDate" type="date" :disabled="locked"></label></div><label v-if="source==='local'" class="retention-log-option"><input v-model="includeLogs" type="checkbox" :disabled="locked||!!workspace">包括过期诊断日志 <small>工作区筛选时不处理公共日志</small></label><div class="preservation-heading"><h4>保留哪些成果</h4><button class="text-button files-only" :disabled="locked" @click="keep={files:true,final:false,decisions:false,code:false}">仅保留输出文件</button></div><div class="preservation-grid"><label v-for="category in categories" :key="category.key" class="preservation-card" :class="{selected:keep[category.key]}"><input v-model="keep[category.key]" type="checkbox" :disabled="locked"><Icon :name="category.icon" :size="19"/><strong>{{ category.name }}</strong><small>{{ category.text }}</small></label></div><p class="retention-disclosure">分类使用可检查的文字与链接规则，不调用模型；重要结论需自行核对。{{ source==='local'?'复制文件限工作区内安全链接、每文件 25 MiB、本次提取每对话 100 MiB；项目原文件始终保留。':'云端附件仅生成链接索引；导出包或链接不等于附件已下载，请先自行保留实际文件。' }}</p></section>
<section class="panel retention-catalog"><div class="section-heading"><div><span class="eyebrow muted">REVIEW BEFORE ACTION</span><h3>逐项核对 <span class="count-badge">{{ filtered.length }}</span></h3><p>{{ selected.length }} 个已选 · 每批最多 20 个 · 可将重要内容固定保护。</p></div><button class="btn secondary select-cleanup-items" :disabled="locked||!eligible.length" @click="selectEligible">选择前 20 个可清理项目</button></div><div v-if="!filtered.length" class="retention-empty"><Icon name="archive" :size="30"/><strong>{{ data.updated?'当前条件没有匹配记录':'尚未扫描' }}</strong><p>{{ source==='local'?'点击扫描本机记录，再调整时间与工作区。':'先导入官方导出包，再按分组与时间筛选。' }}</p></div><div v-else class="retention-item-list"><article v-for="item in visibleItems" :key="item.id" class="retention-item" :class="{protected:!!item.protected}"><input v-model="selected" :value="item.id" type="checkbox" :disabled="locked||!!item.protected" :aria-label="`选择 ${item.name}`"><div class="retention-item-main"><strong>{{ item.name }}</strong><small :title="item.workspace">{{ item.workspace }}</small><div class="retention-item-meta"><span>{{ date(item.updated) }}</span><span>{{ bytes(item.bytes) }}</span><span>{{ item.kind==='log'?'诊断日志':`输出链接 ${item.classification.files||0} · 最终答复 ${item.classification.final||0}` }}</span></div><p v-if="item.protected" class="retention-protected"><Icon name="shield" :size="12"/>{{ item.protected }}</p></div><button class="icon-button pin-retention" :aria-label="data.pinned.includes(item.id)?'取消重要标记':'标记重要'" :aria-pressed="data.pinned.includes(item.id)" :disabled="locked" @click="emit('action','storage.pin',{id:item.id,important:!data.pinned.includes(item.id)},'重要标记已更新。')"><Icon name="pin" :size="17"/></button></article></div><button v-if="filtered.length>visibleLimit" class="btn secondary" style="margin-top:14px;max-width:100%" :disabled="locked" @click="visibleLimit+=100">再显示 100 条 · 已显示 {{ visibleItems.length }}／{{ filtered.length }}</button><div class="retention-catalog-footer"><p>{{ source==='local'?'运行状态会在执行前再次检查，接管失败的目标不会清理。':'导出时间不代表当前云端状态，请在官方页面再次核对。' }}</p><button class="btn primary cleanup-preview" :disabled="locked||!selected.length||selected.length>20||!Object.values(keep).some(Boolean)" @click="requestPreview"><Icon name="eye" :size="16"/>预览{{ source==='local'?'清理':'整理' }}计划</button></div></section>
<Transition name="retention-review"><section v-if="preview" class="panel cleanup-review"><div class="section-heading"><div><span class="eyebrow">READY FOR YOUR REVIEW</span><h3>{{ source==='local'?'确认归档与保留成果':'确认保留成果与云端待办' }}</h3><p>{{ preview.count }} 项 · {{ bytes(preview.bytes) }} 原始记录 · 预览有效期 10 分钟</p></div><Icon name="shield" :size="26"/></div><ul><li v-for="item in preview.items" :key="item.id">{{ item.name }} <span>{{ bytes(item.bytes) }}</span></li></ul><p class="review-effect">{{ source==='local'?'完整原始记录先保留在可恢复回收区，暂不释放磁盘空间。需要释放空间时，在回收区永久清除；保留成果与工作区文件不受影响。':'仅提取本地成果并生成官方待处理清单。云端聊天、附件、记忆与本地导出源记录均保持原样。' }}</p><label class="cleanup-consent"><input v-model="reviewed" type="checkbox" :disabled="locked">我已核对所选项目、保留类别与影响范围</label><button class="btn primary cleanup-execute" :disabled="locked||!reviewed" @click="emit('action','storage.execute',{token:preview.token},source==='local'?'本批已处理，请检查逐项结果与回收区。':'成果与待处理清单已保存，云端尚未改变。')"><Icon name="archive" :size="16"/>{{ source==='local'?'提取成果并移入回收区':'保留成果并生成待处理清单' }}</button></section></Transition>
<section v-if="source==='local'" class="panel application-cache"><div><span class="eyebrow muted">APPLICATION CACHE</span><h3>应用资源缓存</h3><p>{{ cache?bytes(cache.bytes):'尚未读取' }} · 仅 AI Link 自身资源缓存，保留登录、设置、对话和 Codex 状态数据库。</p></div><div class="button-row"><button class="btn ghost" :disabled="locked" @click="readCache">刷新大小</button><button class="btn secondary clear-app-cache" :disabled="locked" @click="native(async()=>{const result=await bridge.appCache(true);cache=result;return result},'AI Link 资源缓存已清理，登录和设置保留。')"><Icon name="refresh" :size="16"/>清理资源缓存</button></div></section>
<section class="panel retention-batches"><div class="section-heading"><div><span class="eyebrow muted">{{ source==='local'?'RECOVERY & RESULTS':'CLOUD ACTION CHECKLIST' }}</span><h3>{{ source==='local'?'回收区与保留成果':'云端待处理清单' }}</h3><p>{{ source==='local'?'归档可恢复；永久清除需再次确认，原始记录删除后不能撤销。':'保留结果与云端处理分开显示，打开原对话后在官方界面操作。' }}</p></div><button class="btn secondary open-retained-files" :disabled="locked" @click="native(()=>bridge.openStorageLocation('library'),'已打开成果与回收区目录。')"><Icon name="folder" :size="16"/>打开成果目录</button></div><p v-if="!batches.length" class="retention-empty-note">处理记录会显示在这里，两个分区各自管理。</p><details v-for="batch in batches" :key="batch.id" class="retention-batch"><summary><span>{{ date(batch.created) }} <code>{{ batch.id.slice(0,8) }}</code></span><span>{{ batch.items.length }} 项 <Icon name="down" :size="15"/></span></summary><div v-for="item in batch.items" :key="item.id" class="retention-batch-item"><div><strong>{{ item.name }}</strong><span>{{ labels[item.state]||item.state }}</span><p v-if="item.error" class="target-error">{{ item.error }}</p><small v-if="item.retained">保留：文件索引 {{ item.retained.files||0 }} · 已复制 {{ item.retained.copied||0 }} · 最终答复 {{ item.retained.final?'有':'无' }}</small></div><button v-if="['archived','quarantined','archive_pending'].includes(item.state)" class="btn secondary restore-retention" :disabled="locked" @click="emit('action','storage.restore',{batchId:batch.id,id:item.id},'已恢复，重新扫描可再次查看。')">恢复原始记录</button><button v-if="item.state==='cloud_pending'" class="btn secondary cloud-handoff" :disabled="locked" @click="native(()=>bridge.openCloudCleanup(item.id),'已打开原云端对话，请在官方页面核对后操作。')"><Icon name="globe" :size="15"/>在官方页面处理</button></div><div v-if="source==='local'&&batch.items.some(i=>['archived','quarantined','restored'].includes(i.state))" class="purge-row"><p>成果保留在原目录；永久清除只处理本批原始记录与恢复备份。</p><button class="btn ghost purge-retention" :disabled="locked" @click="native(()=>bridge.purgeStorageBatch(batch.id),'已处理永久清除请求，请核对各项状态。',true)">永久清除本批原始记录</button></div></details></section>
</div></template>
<style scoped>
.storage-page{--storage-local:#99591f;--storage-cloud:#3f65b5}.storage-hero{display:flex;align-items:center;justify-content:space-between;gap:24px;padding:32px;background:radial-gradient(ellipse at 90% 0,rgba(var(--accent-rgb),.12),transparent 65%),var(--surface);border-color:var(--accent-strong)}.storage-hero h2{font-size:29px;color:var(--text);margin:11px 0}.storage-hero p{font-size:12px;color:var(--muted)}.retention-visual{display:grid;place-items:center;position:relative;isolation:isolate;width:145px;height:130px;flex-shrink:0;color:var(--accent)}.retention-ring{position:absolute;border:1px solid rgba(var(--accent-rgb),.22);border-radius:50%;inset:10px 17px;transform:rotate(-20deg)}.ring-two{inset:25px 0;transform:rotate(30deg);border-style:dashed;animation:retention-orbit 35s linear infinite}.retention-visual>i{position:absolute;width:6px;height:6px;background:var(--accent);border-radius:50%;top:18px;left:30px;box-shadow:0 0 14px rgba(var(--accent-rgb),.2)}.retention-visual>i:nth-of-type(2){left:auto;right:9px;top:70px;opacity:.5}.retention-visual>i:nth-of-type(3){left:48px;top:auto;bottom:6px;opacity:.3}.storage-sources{display:grid;grid-template-columns:1fr 1fr;gap:15px}.storage-source{display:flex;align-items:center;gap:15px;text-align:left;padding:20px 22px;background:var(--surface);border:1px solid var(--line);border-radius:14px;min-width:0;transition:border-color .3s,background .3s;color:var(--muted)}.storage-source>span:not(.source-dot){display:grid;gap:7px;min-width:0}.storage-source strong{font-size:14px;color:var(--text)}.storage-source small{font-size:10px;line-height:1.7;overflow-wrap:anywhere}.local-source{--source-color:var(--storage-local)}.cloud-source{--source-color:var(--storage-cloud)}.storage-source>svg{color:var(--source-color)}.storage-source.selected{border-color:var(--source-color);background:color-mix(in srgb,var(--source-color) 6%,var(--surface))}.source-dot{margin-left:auto;width:8px;height:8px;border:1px solid var(--source-color);border-radius:50%;flex-shrink:0}.selected>.source-dot{background:var(--source-color);box-shadow:0 0 0 5px color-mix(in srgb,var(--source-color) 12%,transparent)}.storage-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:15px}.storage-metrics>article{display:grid;gap:12px;padding:21px 23px}.storage-metrics span{font-size:11px;color:var(--muted)}.storage-metrics strong{font-size:30px;color:var(--text);font-weight:550;font-variant-numeric:tabular-nums}.storage-metrics small{font-size:10px;color:var(--muted);line-height:1.8}.retention-filters{display:grid;grid-template-columns:minmax(0,1.8fr) minmax(0,1fr) repeat(2,minmax(0,1.2fr));gap:13px}.retention-filters>label{display:grid;gap:10px;color:var(--muted);font-size:11px;min-width:0}.retention-filters select,.retention-filters input,.cloud-import-controls input{background:var(--surface-input);color:var(--text);border:1px solid var(--line);border-radius:9px;min-width:0;width:100%;padding:11px 12px;font-size:11px}.retention-filters select{padding-right:20px}.retention-log-option{display:flex;align-items:center;gap:9px;flex-wrap:wrap;font-size:11px;color:var(--text);margin-top:18px}.retention-log-option small{font-size:10px;color:var(--muted)}.preservation-heading{display:flex;align-items:center;justify-content:space-between;gap:13px;margin:26px 0 13px}.preservation-heading h4{margin:0;font-size:12px;font-weight:550;color:var(--text)}.preservation-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.preservation-card{display:grid;grid-template-columns:1fr auto;gap:12px;align-content:start;padding:16px;background:var(--surface-input);border:1px solid var(--line);border-radius:11px;cursor:pointer;min-width:0;transition:background .25s,border-color .25s}.preservation-card>input{grid-column:2;grid-row:1;width:15px;height:15px}.preservation-card>svg{grid-column:1;grid-row:1;color:var(--muted)}.preservation-card strong,.preservation-card small{grid-column:1/-1}.preservation-card strong{font-